async function hideGame(game, button) {
  if (!state.accessToken || Date.now() >= state.accessTokenExpiresAt) {
    say("ç™»å…¥ç‹€æ…‹å·²éæœŸï¼Œè«‹é‡æ–°ç™»å…¥å¾Œå†æ“ä½œã€‚");
    clearToken();
    render();
    return;
  }
  if (!window.confirm(`ç¢ºå®šè¦å¾ç¶²ç«™æ¸…å–®éš±è—ã€Œ${game.title}ã€å—ï¼Ÿ\nåŸå§‹è³‡æ–™æœƒä¿ç•™ï¼Œä¹‹å¾Œä¹Ÿä¸æœƒå› åŒæ­¥è€Œé‡æ–°å‡ºç¾ã€‚`)) return;
  button.disabled = true;
  button.textContent = "è™•ç†ä¸­â€¦";
  try {
    await fetchJson(API + "/games/" + encodeURIComponent(game.id) + "/hide", {
      method: "DELETE",
      headers: { Authorization: "Bearer " + state.accessToken },
    });
    state.games = state.games.filter((item) => item.id !== game.id);
    state.page = 1;
    say(`å·²å°‡ã€Œ${game.title}ã€å¾ç¶²ç«™æ¸…å–®éš±è—ã€‚`);
    render();
  } catch (error) {
    say(error.message);
    render();
  }
}

