async function markClaimed(game, button) {
  if (!state.claimEnabled) {
    say("ç›®å‰å°šæœªè¨­å®š GitHub å¯«å…¥æ¬Šé™ã€‚");
    return;
  }
  if (!state.accessToken || Date.now() >= state.accessTokenExpiresAt) {
    clearToken();
    try {
      sessionStorage.setItem(PENDING_CLAIM_KEY, game.id);
    } catch {
      // å¿½ç•¥
    }
    login();
    return;
  }
  try {
    if (button) {
      button.disabled = true;
      button.textContent = "æ¨™è¨˜ä¸­â€¦";
    }
    const data = await fetchJson(API + "/games/" + encodeURIComponent(game.id) + "/claim", {
      method: "POST",
      headers: {
        Authorization: "Bearer " + state.accessToken,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({}),
    });
    const updated = data.game || {};
    game.claim_status = "claimed";
    game.claimed_at = updated.claimed_at;
    game.claim_source = updated.claim_source;
    say("å·²æ¨™è¨˜ç‚ºé ˜å–ã€‚");
    render();
  } catch (error) {
    say(error.message);
    render();
  }
}

