async function init() {
  setupControls();
  if (restoreToken()) {
    setLoginLabel("å·²ç™»å…¥ Chi Auth", "å·²ç™»å…¥");
  }
  loadVersion();
  await loadConfig();
  await loadGames();
  await finishLogin();
  if (state.accessToken) {
    render();
    const pendingId = readPendingClaim();
    if (pendingId) {
      const game = state.games.find((item) => item.id === pendingId);
      if (game) await markClaimed(game, null);
    }
  }
  if (state.configOk && !state.claimEnabled) {
    say("ç›®å‰å°šæœªè¨­å®š GitHub å¯«å…¥æ¬Šé™ï¼Œæ‰‹å‹•æ¨™è¨˜æš«æ™‚ä¸å¯ç”¨ã€‚");
  }
}

init();
